"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { motion, AnimatePresence } from "framer-motion"
import {
  HeartIcon,
  ThumbsUpIcon,
  LaughIcon,
  FlameIcon,
  PlusIcon,
} from "lucide-react"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export const reactionBarVariants = cva(
  "relative flex items-center justify-center rounded-full transition-all",
  {
    variants: {
      size: {
        sm: "h-8",
        md: "h-10",
        lg: "h-12",
      },
      intent: {
        default: "bg-muted text-muted-foreground",
        primary: "bg-primary text-primary-foreground",
      },
    },
    defaultVariants: {
      size: "md",
      intent: "default",
    },
  }
)

export const reactionMenuVariants = cva(
  "absolute bottom-full mb-2 flex items-center gap-1 rounded-full border bg-background p-1.5 shadow-xl ring-1 ring-black/5",
  {
    variants: {
      size: {
        sm: "h-10",
        md: "h-12",
        lg: "h-14",
      },
    },
    defaultVariants: {
      size: "md",
    },
  }
)

export interface ReactionType {
  id: string
  label: string
  icon: React.ReactNode
  colorClass?: string
}

const DEFAULT_REACTIONS: ReactionType[] = [
  {
    id: "heart",
    label: "Love",
    icon: <HeartIcon className="fill-current" />,
    colorClass:
      "text-rose-500 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/50",
  },
  {
    id: "thumbs-up",
    label: "Like",
    icon: <ThumbsUpIcon className="fill-current" />,
    colorClass:
      "text-blue-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-950/50",
  },
  {
    id: "laugh",
    label: "Haha",
    icon: <LaughIcon />,
    colorClass:
      "text-amber-500 hover:text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-950/50",
  },
  {
    id: "flame",
    label: "Fire",
    icon: <FlameIcon className="fill-current" />,
    colorClass:
      "text-orange-500 hover:text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-950/50",
  },
]

export interface ReactionBarProps
  extends
    React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof reactionBarVariants> {
  reactions?: ReactionType[]
  value?: string | null
  onReact?: (id: string | null) => void
  disabled?: boolean
}

export const ReactionBar = React.forwardRef<HTMLDivElement, ReactionBarProps>(
  (
    {
      className,
      size,
      intent,
      reactions = DEFAULT_REACTIONS,
      value = null,
      onReact,
      disabled = false,
      ...props
    },
    ref
  ) => {
    const [isHovered, setIsHovered] = React.useState(false)
    const [isFocused, setIsFocused] = React.useState(false)

    const isOpen = !disabled && (isHovered || isFocused)
    const activeReaction = reactions.find((r) => r.id === value)

    const handleReact = (id: string) => {
      if (disabled) return
      if (value === id) {
        onReact?.(null)
      } else {
        onReact?.(id)
      }
      setIsFocused(false)
      setIsHovered(false)
    }

    const iconSizeClass =
      size === "sm" ? "size-3.5" : size === "md" ? "size-4" : "size-5"
    const menuIconSizeClass =
      size === "sm" ? "size-4" : size === "md" ? "size-5" : "size-6"

    return (
      <div
        className="relative inline-flex flex-col items-center"
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        ref={ref}
        {...props}
      >
        <AnimatePresence>
          {isOpen && (
            <motion.div
              initial={{ opacity: 0, y: 10, scale: 0.9 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.9 }}
              transition={{ type: "spring", bounce: 0.3, duration: 0.4 }}
              className={cn(reactionMenuVariants({ size }))}
              role="group"
              aria-label="Reactions"
            >
              {reactions.map((reaction, index) => (
                <motion.div
                  key={reaction.id}
                  initial={{ opacity: 0, y: 10, scale: 0.5 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  transition={{
                    delay: index * 0.05,
                    type: "spring",
                    bounce: 0.4,
                  }}
                >
                  <Button
                    variant="ghost"
                    size="icon"
                    className={cn(
                      "rounded-full transition-transform hover:scale-125 focus-visible:scale-125",
                      size === "sm"
                        ? "size-7"
                        : size === "md"
                          ? "size-9"
                          : "size-11",
                      reaction.colorClass
                    )}
                    onClick={() => handleReact(reaction.id)}
                    onFocus={() => setIsFocused(true)}
                    onBlur={() => setIsFocused(false)}
                    aria-label={`React with ${reaction.label}`}
                    aria-pressed={value === reaction.id}
                  >
                    <span
                      className={cn(
                        menuIconSizeClass,
                        "flex items-center justify-center"
                      )}
                    >
                      {React.cloneElement(reaction.icon as React.ReactElement, {
                        className: "size-full",
                      })}
                    </span>
                  </Button>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>

        <Button
          variant={intent === "primary" ? "default" : "secondary"}
          size={size}
          className={cn(
            "gap-2 rounded-full px-4 shadow-sm transition-all duration-300",
            activeReaction &&
              intent === "default" &&
              "border bg-background shadow-sm",
            activeReaction &&
              intent === "primary" &&
              "bg-primary text-primary-foreground",
            className
          )}
          disabled={disabled}
          onClick={() => {
            if (activeReaction) {
              handleReact(activeReaction.id)
            } else {
              setIsFocused(!isFocused)
            }
          }}
          onFocus={() => setIsFocused(true)}
          onBlur={() => {
            setTimeout(() => setIsFocused(false), 200)
          }}
          aria-expanded={isOpen}
          aria-haspopup="true"
        >
          <AnimatePresence mode="popLayout" initial={false}>
            {activeReaction ? (
              <motion.span
                key={activeReaction.id}
                initial={{ scale: 0, rotate: -45 }}
                animate={{ scale: 1, rotate: 0 }}
                exit={{ scale: 0, rotate: 45 }}
                className={cn("flex items-center", activeReaction.colorClass)}
              >
                {React.cloneElement(activeReaction.icon as React.ReactElement, {
                  className: iconSizeClass,
                })}
              </motion.span>
            ) : (
              <motion.span
                key="plus"
                initial={{ scale: 0, rotate: 45 }}
                animate={{ scale: 1, rotate: 0 }}
                exit={{ scale: 0, rotate: -45 }}
                className="flex items-center text-muted-foreground"
              >
                <PlusIcon className={iconSizeClass} />
              </motion.span>
            )}
          </AnimatePresence>
          <span className="text-sm font-medium">
            {activeReaction ? activeReaction.label : "React"}
          </span>
        </Button>
      </div>
    )
  }
)
ReactionBar.displayName = "ReactionBar"
